void FFluidFlowEditorModuleModule::StartupModule()
{
	UE_LOG(LogTemp, Log, TEXT("FluidFlowEditorModule has started!"));
	
	// Register shader directory (guarded against duplicate auto-registration)
	if (!AllShaderSourceDirectoryMappings().Contains(TEXT("/Plugin/FluidFlow")))
	{
		FString PluginShaderDir = FPaths::Combine(IPluginManager::Get().FindPlugin(TEXT("FluidFlow"))->GetBaseDir(), TEXT("Shaders"));
		AddShaderSourceDirectoryMapping(TEXT("/Plugin/FluidFlow"), PluginShaderDir);
	}
}

void FFluidFlowEditorModuleModule::ShutdownModule()
{
	UE_LOG(LogTemp, Log, TEXT("FluidFlowEditorModule has shut down!"));
}

